Here is the Swift `User` model with `Codable`, a custom `ISO8601DateFormatter` for fractional-second timestamps, `CodingKeys` mapping `created_at` → `createdAt`, and a `do/catch` decode example:

```swift
import Foundation

struct User: Codable {
    let id: Int
    let name: String
    let email: String
    let createdAt: Date

    // MARK: - CodingKeys

    private enum CodingKeys: String, CodingKey {
        case id
        case name
        case email
        case createdAt = "created_at"
    }

    // MARK: - Date Formatter

    private static let iso8601Formatter: ISO8601DateFormatter = {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return formatter
    }()

    // MARK: - Decoding

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = try container.decode(Int.self, forKey: .id)
        name = try container.decode(String.self, forKey: .name)
        email = try container.decode(String.self, forKey: .email)

        let dateString = try container.decode(String.self, forKey: .createdAt)
        guard let date = User.iso8601Formatter.date(from: dateString) else {
            throw DecodingError.dataCorruptedError(
                forKey: .createdAt,
                in: container,
                debugDescription: "Invalid ISO8601 date string: \(dateString)"
            )
        }
        createdAt = date
    }

    // MARK: - Encoding

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(id, forKey: .id)
        try container.encode(name, forKey: .name)
        try container.encode(email, forKey: .email)

        let dateString = User.iso8601Formatter.string(from: createdAt)
        try container.encode(dateString, forKey: .createdAt)
    }
}

// MARK: - Usage Example

let json = """
{
    "id": 1,
    "name": "Jane Doe",
    "email": "jane@example.com",
    "created_at": "2026-07-25T10:30:00.123Z"
}
"""

do {
    let data = Data(json.utf8)
    let user = try JSONDecoder().decode(User.self, from: data)
    print(user)
} catch {
    print("Decoding failed: \(error)")
}
```

